5|
6|const usage = `Usage: node dist/main.js [options]
7|
8|  --config PATH             device and room layout (default config.json)
9|  --matter-storage DIR      Matter fabric and pairing data (default data/matter)
10|  --bluetooth-adapter ID    HCI id of the adapter for Bluetooth pairing (default: off)
11|  --no-matter               run without the Matter controller (Govee-only homes, tests)`;
12|
13|export interface CliOptions {
14|  config: string;
15|  matterStorage: string;
16|  /** HCI id of the Bluetooth adapter; null leaves Bluetooth off. */
17|  bluetoothAdapter: number | null;
18|  matter: boolean;
19|}
20|
21|export function parseCli(argv: string[]): CliOptions {
22|  const { values } = parseArgs({
23|    args: argv,
24|    options: {
25|      config: { type: "string", default: "config.json" },
26|      "matter-storage": { type: "string", default: "data/matter" },
27|      "bluetooth-adapter": { type: "string" },
28|      "no-matter": { type: "boolean", default: false },
29|      help: { type: "boolean", short: "h", default: false },
